from collections import deque

def transform(grid):
    non_bg = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] not in [0, 5]:
                non_bg.add((r, c))

    def flood_fill(start, component, color):
        queue = deque([start])
        component.add(start)
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                neighbor = (nr, nc)
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] == color and neighbor not in component:
                        component.add(neighbor)
                        queue.append(neighbor)

    visited = set()
    shapes = []
    for r, c in sorted(non_bg):
        if (r, c) not in visited:
            color = grid[r][c]
            component = set()
            flood_fill((r, c), component, color)
            for cell in component:
                visited.add(cell)
            shapes.append(component)

    result_shapes = []
    for component in shapes:
        cells = sorted(component)
        min_r = min(c[0] for c in cells)
        max_r = max(c[0] for c in cells)
        min_c = min(c[1] for c in cells)
        max_c = max(c[1] for c in cells)

        shape_3x3 = [[0]*3 for _ in range(3)]
        cr = 0
        for rr in range(min_r, max_r + 1):
            c = 0
            for cc in range(min_c, max_c + 1):
                if (rr, cc) in component:
                    shape_3x3[cr][c] = grid[rr][cc]
                c += 1
            cr += 1

        while len(shape_3x3) < 3:
            shape_3x3.append([0,0,0])
        while len(shape_3x3[0]) < 3:
            for row in shape_3x3:
                row.extend([0]*(3-len(row)))

        result_shapes.append((min_c, shape_3x3))

    result_shapes.sort(key=lambda x: x[0])

    output = []
    for r in range(3):
        output.append(sum(shape_3x3[r] for _, shape_3x3 in result_shapes))

    return output

